        "type": "component",
        "name": "role-columns.tsx",
        "code": "\"use client\"\n\nimport { createColumnHelper } from \"@tanstack/react-table\"\nimport { EllipsisIcon, ListChecksIcon, PencilIcon } from \"lucide-react\"\nimport { useCallback, useRef } from \"react\"\n\nimport { Button } from \"@/components/ui/button\"\nimport {\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuItem,\n  DropdownMenuTrigger,\n} from \"@/components/ui/dropdown-menu\"\nimport {\n  DataTableColumnHeader,\n  type DataTableFeatures,\n} from \"@/components/blocks/openlmis/data-table/data-table\"\nimport type { ResponsiveColumn } from \"@/components/blocks/openlmis/data-table/responsive-columns\"\nimport { roleTypeOf } from \"@/components/blocks/openlmis/role-assignments-table/role-assignments\"\nimport { roleTypeInfo } from \"@/components/blocks/openlmis/role-form-dialog/role-form\"\n\nimport type { ListedRole } from \"@/components/openlmis/roles-page/mock-roles\"\n\n/** The columns the View menu lists, in order; the role's name is left out, so it always shows. */\nexport const HIDEABLE_COLUMNS: (ResponsiveColumn & { label: string })[] = [\n  { id: \"type\", label: \"Role Type\", hideBelow: \"md\" },\n  { id: \"description\", label: \"Description\", hideBelow: \"4xl\" },\n  { id: \"count\", label: \"Number Of Users\", hideBelow: \"xl\" },\n]\n\nconst columnHelper = createColumnHelper<DataTableFeatures, ListedRole>()\n\n/** Each is left out when the user may not do it, and the menu goes when both are. */\nexport type RoleRowActions = {\n  onEdit?: ((roleId: string) => void) | undefined\n  onViewRights?: ((roleId: string) => void) | undefined\n}\n\nexport function createRoleColumns(actions: RoleRowActions) {\n  const hasActions = Boolean(actions.onEdit || actions.onViewRights)\n  return columnHelper.columns([\n    columnHelper.accessor(\"name\", {\n      header: ({ column }) => (\n        <DataTableColumnHeader column={column} title=\"Role\" />\n      ),\n      cell: ({ getValue }) => <span className=\"font-medium\">{getValue()}</span>,\n      meta: { className: \"@xl/table:w-1/3 @4xl/table:w-1/4\" },\n    }),\n    columnHelper.accessor((role) => roleTypeOf(role), {\n      id: \"type\",\n      header: ({ column }) => (\n        <DataTableColumnHeader column={column} title=\"Role Type\" />\n      ),\n      cell: ({ getValue }) => {\n        const type = getValue()\n        return type ? (\n          roleTypeInfo(type).label\n        ) : (\n          <span className=\"text-muted-foreground\">No Type</span>\n        )\n      },\n      meta: { className: \"@xl/table:w-40\" },\n    }),\n    columnHelper.accessor(\"description\", {\n      header: ({ column }) => (\n        <DataTableColumnHeader column={column} title=\"Description\" />\n      ),\n      cell: ({ getValue }) =>\n        getValue() || <span className=\"text-muted-foreground\">-</span>,\n      enableSorting: false,\n    }),\n    columnHelper.accessor(\"count\", {\n      header: ({ column }) => (\n        <DataTableColumnHeader column={column} title=\"Number Of Users\" />\n      ),\n      cell: ({ getValue }) => (\n        <span className=\"tabular-nums\">{getValue()}</span>\n      ),\n      meta: { className: \"w-36\" },\n    }),\n    ...(hasActions\n      ? [\n          columnHelper.display({\n            id: \"actions\",\n            header: () => <span className=\"sr-only\">Actions</span>,\n            cell: ({ row }) => (\n              <RoleActions actions={actions} role={row.original} />\n            ),\n            meta: { className: \"w-16\" },\n          }),\n        ]\n      : []),\n  ])\n}\n\n/** Keeps a closing menu from taking focus back to its trigger when an item opened a dialog, which then owns focus. */\nfunction useMenuOpensDialog() {\n  const opened = useRef(false)\n\n  const onOpenChange = useCallback((open: boolean) => {\n    if (open) opened.current = false\n  }, [])\n  const finalFocus = useCallback(() => !opened.current, [])\n  const opensDialog = useCallback(\n    (open: () => void) => () => {\n      opened.current = true\n      open()\n    },\n    []\n  )\n\n  return { onOpenChange, finalFocus, opensDialog }\n}\n\nfunction RoleActions({\n  role,\n  actions: { onEdit, onViewRights },\n}: {\n  role: ListedRole\n  actions: RoleRowActions\n}) {\n  const menu = useMenuOpensDialog()\n\n  return (\n    <div className=\"flex justify-end\">\n      <DropdownMenu onOpenChange={menu.onOpenChange}>\n        <DropdownMenuTrigger\n          render={\n            <Button\n              aria-label={`Actions for ${role.name}`}\n              size=\"icon-sm\"\n              variant=\"ghost\"\n            />\n          }\n        >\n          <EllipsisIcon />\n        </DropdownMenuTrigger>\n        <DropdownMenuContent\n          align=\"end\"\n          className=\"w-auto\"\n          finalFocus={menu.finalFocus}\n        >\n          {onEdit && (\n            <DropdownMenuItem onClick={menu.opensDialog(() => onEdit(role.id))}>\n              <PencilIcon />\n              Edit\n            </DropdownMenuItem>\n          )}\n          {onViewRights && (\n            <DropdownMenuItem\n              onClick={menu.opensDialog(() => onViewRights(role.id))}\n            >\n              <ListChecksIcon />\n              View Rights\n            </DropdownMenuItem>\n          )}\n        </DropdownMenuContent>\n      </DropdownMenu>\n    </div>\n  )\n}",
