        "code": "import { HomeDashboard } from \"@/components/openlmis/home-dashboard/home-dashboard\"\n\n// A Next.js App Router route; in any other React app, render HomeDashboard from your own route.\nexport default function Page() {\n  return <HomeDashboard />\n}",
